import java.util.*; import java.io.*; public class Main { public static void main(String[] args) throws IOException { BufferedReader br = new BufferedReader(new InputStreamReader(System.in)); PrintWriter out = new PrintWriter(System.out); String line = br.readLine(); if (line != null) { int t = Integer.parseInt(line.trim()); while (t-- > 0) { int n = Integer.parseInt(br.readLine().trim()); int start = 251; for (int i = 0; i < n; i++) { out.print((start + i) + (i == n - 1 ? "" : " ")); } out.println(); } } out.flush(); out.close(); } }